{"expression": "(() => {
  const out = {searchInputs: [], panes: []};
  document.querySelectorAll('div[contenteditable="true"][role="textbox"], input[type="text"]').forEach((el,i)=>{
    out.searchInputs.push({i, tag: el.tagName, aria: el.getAttribute('aria-label'), dataTestId: el.getAttribute('data-testid'), placeholder: el.getAttribute('aria-placeholder')||el.getAttribute('placeholder'), text: (el.innerText||el.value||'').slice(0,50)});
  });
  out.panes = [...document.querySelectorAll('#pane-side, #main')].map(e=>e.id);
  return JSON.stringify(out);
})()"}

{"expression": "(() => {
  const input = document.querySelector('input[aria-label="Pesquisar ou começar uma nova conversa"]');
  if (!input) return 'no input';
  input.focus();
  const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
  setter.call(input, 'Kevyn ACIRV');
  input.dispatchEvent(new Event('input', {bubbles: true}));
  return 'typed: ' + input.value;
})()"}

{"expression": "(() => {
  const pane = document.querySelector('#pane-side');
  const rows = [...document.querySelectorAll('#pane-side [role="listitem"], #pane-side [role="row"]')];
  return JSON.stringify(rows.slice(0,12).map((r,i)=>({i, text: r.innerText.replace(/\n+/g,' | ').slice(0,160)})));
})()"}

{"expression": "(() => {
  const rows = [...document.querySelectorAll('#pane-side [role="listitem"], #pane-side [role="row"]')];
  const row = rows[1];
  if (!row) return 'no row';
  const clickable = row.querySelector('[role="button"], [tabindex]') || row;
  clickable.dispatchEvent(new MouseEvent('mousedown', {bubbles:true}));
  clickable.dispatchEvent(new MouseEvent('mouseup', {bubbles:true}));
  clickable.click();
  return 'clicked: ' + row.innerText.replace(/\n+/g,' | ').slice(0,80);
})()"}

{"expression": "(() => {
  const main = document.querySelector('#main');
  if (!main) return 'no #main yet';
  const header = main.querySelector('header');
  const boxes = [...main.querySelectorAll('div[contenteditable="true"]')].map(el=>({aria: el.getAttribute('aria-label'), text:(el.innerText||'').slice(0,40)}));
  return JSON.stringify({header: header ? header.innerText.replace(/\n+/g,' | ').slice(0,120) : null, boxes});
})()"}

{"expression": "(() => {
  const main = document.querySelector('#main');
  if(!main) return 'no main';
  const rows = [...main.querySelectorAll('[data-testid="msg-container"]')];
  const last = rows.slice(-3).map(r=>({
    text: r.innerText.replace(/\n+/g,' | ').slice(0,120),
    out: r.querySelector('[data-testid="msg-out"], .message-out') ? true : (!!r.querySelector('[aria-label*="Entregue"], [data-icon="msg-check"], [data-icon="msg-dblcheck"]'))
  }));
  const footerBox = main.querySelector('footer div[contenteditable="true"]');
  return JSON.stringify({count: rows.length, last, composeEmpty: (footerBox?.innerText||'').trim()==='' });
})()"}

{"expression": "(() => {
  const main = document.querySelector('#main');
  if (!main) return 'no main';
  const box = main.querySelector('footer div[contenteditable="true"]');
  if (!box) return 'no box';
  const text = "*O futuro da inteligência humana na era da IA — resumo*\n\n1) A vantagem deixou de ser técnica. O AI Index 2026 (Stanford HAI) mostra modelos já igualando ou superando humanos em tarefas técnicas (programação, análise de dados), mas falhando em raciocínio aberto, noção de tempo e sequenciamento. O diferencial migra para julgamento, contexto e ética.\n\n2) WEF + McKinsey Health (\"The Human Advantage\", 2026) cunharam \"brain capital\": saúde cerebral + habilidades cognitivas e socioemocionais como ativo econômico estratégico. Competências-chave: autorregulação, pensamento crítico, criatividade, adaptabilidade e aprendizagem contínua. Até 2030, ~59% dos trabalhadores precisarão de requalificação.\n\n3) IA virou alfabetização básica. No Brasil, vagas que exigem skills de IA quase triplicaram: 63 mil → 182 mil (2024-2025). Quando a ferramenta vira commodity, o valor volta ao que não se automatiza: empatia, influência, julgamento, liderança (framework do MIT).\n\n4) A neurociência confirma o limite: inteligência humana é adaptação para aprender com poucos exemplos, socializar e antecipar o futuro — coisa que a IA não faz fora de ambiente controlado.\n\n*Síntese:* o futuro não é IA vs. humano, é inteligência híbrida. O profissional mais valioso da próxima década não é quem produz mais respostas, mas quem sabe quais perguntar.\n\nFontes: Stanford HAI (AI Index 2026), WEF/McKinsey (The Human Advantage), Época Negócios (out/2026), Folha Ilustríssima (ago/2026).";
  box.focus();
  document.execCommand('selectAll', false, null);
  document.execCommand('insertText', false, text);
  return JSON.stringify({len: (box.innerText||'').length, head: (box.innerText||'').slice(0,60)});
})()"}

